669	        /// thread_create：在当前进程中创建新线程
670	        ///
671	        /// 为新线程分配独立的用户栈（从高地址向下搜索未映射的页面），
672	        /// 创建新的执行上下文，入口为 entry，参数为 arg。
673	        fn thread_create(&self, _caller: Caller, entry: usize, arg: usize) -> isize {
674	            let processor: *mut ProcessorInner = PROCESSOR.get_mut() as *mut ProcessorInner;
675	            let current_proc = unsafe { (*processor).get_current_proc().unwrap() };
676	            // 从最高用户栈位置向下搜索空闲的页表区域
677	            let mut vpn = VPN::<Sv39>::new((1 << 26) - 2);
678	            let addrspace = &mut current_proc.address_space;
679	            loop {
680	                let idx = vpn.index_in(Sv39::MAX_LEVEL);
681	                if !addrspace.root()[idx].is_valid() { break; }
682	                vpn = VPN::<Sv39>::new(vpn.val() - 3);
683	            }
684	            // 分配 2 页用户栈
685	            let stack = unsafe {
686	                alloc_zeroed(Layout::from_size_align_unchecked(
687	                    2 << Sv39::PAGE_BITS, 1 << Sv39::PAGE_BITS,
688	                ))
689	            };
690	            addrspace.map_extern(vpn..vpn + 2, PPN::new(stack as usize >> Sv39::PAGE_BITS), build_flags("U_WRV"));
691	            let satp = (8 << 60) | addrspace.root_ppn().val();
692	            let mut context = tg_kernel_context::LocalContext::user(entry);
693	            *context.sp_mut() = (vpn + 2).base().val();
694	            *context.a_mut(0) = arg;
695	            let thread = Thread::new(satp, context);
696	            let tid = thread.tid;
697	            unsafe { (*processor).add(tid, thread, current_proc.pid); }
698	            tid.get_usize() as _
699	        }

